#!/usr/bin/env python3
import paramiko
import yaml

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

# 1. Read automations
stdin, stdout, stderr = ssh.exec_command('cat /config/automations.yaml')
auto_yaml = stdout.read().decode()

data = yaml.safe_load(auto_yaml)

# Find our automation and update it
for i, a in enumerate(data):
    if a.get('id') == 'peak_hours_ac_enforce':
        a['mode'] = 'single'
        a['initial_state'] = True
        a['actions'] = [
            {
                'variables': {
                    'acs_to_turn_off': "{% set climate_acs = ['climate.tac', 'climate.bac', 'climate.dac', 'climate.lacgf'] %} {{ expand(climate_acs) | selectattr('state', 'ne', 'off') | rejectattr('entity_id', 'eq', trigger.entity_id) | map(attribute='entity_id') | list }}"
                }
            },
            {
                'if': [
                    {
                        'condition': 'template',
                        'value_template': "{{ acs_to_turn_off | length > 0 }}"
                    }
                ],
                'then': [
                    {
                        'action': 'climate.turn_off',
                        'target': {
                            'entity_id': "{{ acs_to_turn_off }}"
                        }
                    }
                ]
            },
            {
                'if': [
                    {
                        'condition': 'template',
                        'value_template': "{{ trigger.entity_id != 'switch.gac_switch' and states('switch.gac_switch') == 'on' }}"
                    }
                ],
                'then': [
                    {
                        'action': 'switch.turn_off',
                        'target': {
                            'entity_id': 'switch.gac_switch'
                        }
                    }
                ]
            },
            {
                'action': 'persistent_notification.create',
                'data': {
                    'title': 'Peak Hours AC Limit',
                    'message': "Only {{ trigger.to_state.name }} is allowed during peak hours. Other ACs have been turned off."
                }
            },
            {
                'delay': {
                    'seconds': 5
                }
            }
        ]

new_yaml = yaml.dump(data, default_flow_style=False, sort_keys=False)

# Write back
import base64
encoded = base64.b64encode(new_yaml.encode()).decode()
cmd = f"sudo python3 -c \"import base64; open('/config/automations.yaml','w').write(base64.b64decode('{encoded}').decode())\""
ssh.exec_command(cmd)

# Reload automations
ssh.exec_command("sudo curl -s -X POST -H 'Authorization: Bearer $(cat /config/.storage/auth 2>/dev/null | python3 -c \"import sys,json; print([t[\\'token\\'] for t in json.load(sys.stdin)[\\'data\\'][\\'refresh_tokens\\'] if t.get(\\'token_type\\')==\\'long_lived_access_token\\'][0])\" 2>/dev/null)' -H 'Content-Type: application/json' http://localhost:8123/api/services/automation/reload 2>/dev/null")

ssh.close()

