#!/usr/bin/env python3
import paramiko
import json
import base64

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

# Read current dashboard
stdin, stdout, stderr = ssh.exec_command("sudo cat /config/.storage/lovelace.dashboard_kiosk")
dash = json.loads(stdout.read().decode())

# Find and remove the SmartLoad card from the horizontal-stack
views = dash['data']['config']['views']
for view in views:
    for card in view.get('cards', []):
        if card.get('type') == 'vertical-stack':
            for sub in card.get('cards', []):
                if sub.get('type') == 'horizontal-stack':
                    for hsub in sub.get('cards', []):
                        if hsub.get('type') == 'vertical-stack':
                            for vsub in hsub.get('cards', []):
                                if vsub.get('type') == 'horizontal-stack':
                                    vsub['cards'] = [c for c in vsub['cards'] if c.get('entity') != 'switch.inverter_smartload']

# Write back
dash_json = json.dumps(dash, indent=2)
encoded = base64.b64encode(dash_json.encode()).decode()
cmd = f"sudo python3 -c \"import base64; open('/config/.storage/lovelace.dashboard_kiosk','w').write(base64.b64decode('{encoded}').decode())\""
stdin, stdout, stderr = ssh.exec_command(cmd)
stdout.read()

ssh.close()
print("SmartLoad button removed!")

