#!/usr/bin/env python3
import paramiko
import json
import re

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

def run(cmd):
    stdin, stdout, stderr = ssh.exec_command(cmd)
    return stdout.read().decode().strip()

print("=== 1. Checking core.config_entries for generic cameras ===")
try:
    entries_data = run("sudo cat /config/.storage/core.config_entries")
    if entries_data:
        entries = json.loads(entries_data)
        for entry in entries['data']['entries']:
            if entry['domain'] in ['generic', 'onvif', 'webrtc', 'rtsp_to_webrtc']:
                print(f"Integration: {entry['domain']}")
                print(f"Title: {entry.get('title')}")
                if 'data' in entry:
                    # Obfuscate passwords in URLs if any
                    data_str = json.dumps(entry['data'], indent=2)
                    data_str = re.sub(r'rtsp://([^:]+):([^@]+)@', r'rtsp://\1:***@', data_str)
                    print(data_str)
                print("---")
except Exception as e:
    print("Error reading config_entries:", e)

print("\n=== 2. Checking configuration.yaml for 'camera' domain ===")
camera_config = run("sudo cat /config/configuration.yaml | grep -iA 20 'camera:'")
if camera_config:
    # Obfuscate
    camera_config = re.sub(r'rtsp://([^:]+):([^@]+)@', r'rtsp://\1:***@', camera_config)
    print(camera_config)
else:
    print("No 'camera:' section found.")

print("\n=== 3. Checking for go2rtc.yaml ===")
go2rtc = run("sudo cat /config/go2rtc.yaml 2>/dev/null")
if go2rtc:
    go2rtc = re.sub(r'rtsp://([^:]+):([^@]+)@', r'rtsp://\1:***@', go2rtc)
    print(go2rtc)
else:
    print("No go2rtc.yaml found.")

ssh.close()

