#!/usr/bin/env python3
import paramiko
import json
import base64

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

stdin, stdout, stderr = ssh.exec_command("sudo cat /config/.storage/lovelace.dashboard_kiosk")
content = stdout.read().decode()

if not content:
    print("Dashboard not found!")
    exit(1)

dash = json.loads(content)

views = dash['data']['config']['views']

# 1. Add "Cameras" button to the main view
def add_button_to_controls(obj):
    if isinstance(obj, dict):
        # Find the Controls horizontal stack
        if obj.get('type') == 'horizontal-stack':
            cards = obj.get('cards', [])
            if len(cards) > 0 and cards[0].get('entity') == 'switch.water_geyser_switch':
                # Add the cameras button
                cam_btn = {
                    "type": "custom:mushroom-template-card",
                    "primary": "Cameras",
                    "icon": "mdi:cctv",
                    "layout": "vertical",
                    "tap_action": {
                        "action": "navigate",
                        "navigation_path": "/dashboard-kiosk/cameras"
                    },
                    "card_mod": {
                        "style": "ha-card { padding: 8px !important; } mushroom-state-info { --card-primary-font-size: 13px; }"
                    }
                }
                # check if it's already there
                has_cam = any(c.get('primary') == 'Cameras' for c in cards)
                if not has_cam:
                    cards.append(cam_btn)
                return True
        for key, val in obj.items():
            add_button_to_controls(val)
    elif isinstance(obj, list):
        for item in obj:
            add_button_to_controls(item)

add_button_to_controls(views[0])

# 2. Add the subview for cameras
has_cam_view = any(v.get('path') == 'cameras' for v in views)
if not has_cam_view:
    cam_streams = [
        ("Right Street", "right_street"),
        ("Gate Cam", "gate_cam"),
        ("Dirty Kitchen", "dirty_kitchen"),
        ("Back Street", "back_street"),
        ("Hallway Cam", "hallway_cam"),
        ("Kitchen Street", "kitchen_street")
    ]

    # Group in pairs for 2-column layout (horizontal stacks)
    cam_rows = []
    for i in range(0, len(cam_streams), 2):
        row_cards = []
        for name, stream in cam_streams[i:i+2]:
            row_cards.append({
                "type": "custom:webrtc-camera",
                "url": stream,
                "title": name,
                "ui": True,
                "muted": True
            })
        cam_rows.append({
            "type": "horizontal-stack",
            "cards": row_cards
        })

    cam_view = {
        "title": "Cameras",
        "path": "cameras",
        "subview": True,
        "type": "panel",
        "cards": [
            {
                "type": "vertical-stack",
                "cards": cam_rows
            }
        ]
    }
    views.append(cam_view)

dash_json = json.dumps(dash, indent=2)
encoded = base64.b64encode(dash_json.encode()).decode()
cmd = f"sudo python3 -c \"import base64; open('/config/.storage/lovelace.dashboard_kiosk','w').write(base64.b64decode('{encoded}').decode())\""
ssh.exec_command(cmd)

ssh.close()
print("Successfully added cameras subview and button!")

