#!/usr/bin/env python3
import paramiko
import json
import base64

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

stdin, stdout, stderr = ssh.exec_command('sudo cat /config/.storage/lovelace.dashboard_kiosk')
content = stdout.read().decode()
if not content: exit(1)
dash = json.loads(content)

# Traverse down to find the power-flow-card-plus and mushroom-chips-card in Energy section
for view in dash.get('data', {}).get('config', {}).get('views', []):
    for card in view.get('cards', []):
        if card.get('type') == 'vertical-stack':
            # This might be the Energy stack
            for subcard in card.get('cards', []):
                if subcard.get('type') == 'custom:power-flow-card-plus':
                    if 'battery' in subcard.get('entities', {}):
                        del subcard['entities']['battery']
                if subcard.get('type') == 'custom:mushroom-chips-card' and 'chips' in subcard:
                    # Remove any chip that has 'sensor.inverter_battery'
                    subcard['chips'] = [chip for chip in subcard['chips'] if 'sensor.inverter_battery' not in chip.get('content', '')]

dash_json = json.dumps(dash, indent=2)
encoded = base64.b64encode(dash_json.encode()).decode()
cmd = f"sudo python3 -c \"import base64; open('/config/.storage/lovelace.dashboard_kiosk','w').write(base64.b64decode('{encoded}').decode())\""
ssh.exec_command(cmd)

ssh.close()
print("Solar battery removed from dashboard.")

