#!/usr/bin/env python3
import paramiko
import yaml
import sys

ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
ssh.connect('192.168.86.41', username='hassio', password='Malhi5$2')

# Fetch automations.yaml
stdin, stdout, stderr = ssh.exec_command('sudo docker exec homeassistant cat /config/automations.yaml')
out = stdout.read().decode()

try:
    data = yaml.safe_load(out)
except Exception as e:
    print("Error loading yaml:", e)
    sys.exit(1)

found = False
for auto in data:
    if auto.get('id') == 'peak_hours_ac_enforce':
        found = True
        # Update triggers
        auto['triggers'] = [
            {
                'trigger': 'state',
                'entity_id': ['climate.tac', 'climate.bac', 'climate.dac', 'climate.lacgf'],
                'to': ['cool', 'dry', 'heat', 'fan_only', 'auto']
            },
            {
                'trigger': 'state',
                'entity_id': 'switch.gac_switch',
                'to': 'on'
            }
        ]

        # Update acs_to_turn_off variable logic
        if 'actions' in auto:
            for action in auto['actions']:
                if 'variables' in action and 'acs_to_turn_off' in action['variables']:
                    action['variables']['acs_to_turn_off'] = "{% set climate_acs = ['climate.tac', 'climate.bac', 'climate.dac', 'climate.lacgf'] %}\n{{ expand(climate_acs) | rejectattr('state', 'in', ['off', 'unavailable', 'unknown']) | rejectattr('entity_id', 'eq', trigger.entity_id) | map(attribute='entity_id') | list }}\n"

if found:
    new_yaml = yaml.dump(data, default_flow_style=False, sort_keys=False)
    # Write back
    import base64
    encoded = base64.b64encode(new_yaml.encode()).decode()
    cmd = f"echo '{encoded}' | base64 -d | sudo docker exec -i homeassistant tee /config/automations.yaml > /dev/null"
    stdin, stdout, stderr = ssh.exec_command(cmd)

    # Reload automations
    ssh.exec_command('sudo docker exec homeassistant curl -s -X POST http://supervisor/core/api/services/automation/reload -H "Authorization: Bearer $(cat /config/.storage/core.restore_state.objects 2>/dev/null | head -1)"')

    print("Automation updated successfully!")
else:
    print("Could not find peak_hours_ac_enforce automation.")

ssh.close()

